public:
    int maxGoodNumber(vector<int>& nums) {
        int best = 0;
        int perms[6][3] = {{0,1,2},{0,2,1},{1,0,2},{1,2,0},{2,0,1},{2,1,0}};
        for (auto& p : perms) {
            int v = 0;
            for (int idx : p) {
                int x = nums[idx], bl = 0;
                while ((1 << bl) <= x) bl++;
                v = (v << bl) | x;
            }
            best = max(best, v);
        }
        return best;
    }
};

