from functools import cmp_to_key
class Solution:
    def maxGoodNumber(self, nums: List[int]) -> int:
        def cat(a, b):
            return (a << b.bit_length()) | b
        arr = sorted(nums, key=cmp_to_key(lambda a, b: cat(b, a) - cat(a, b)))
        v = 0
        for x in arr:
            v = (v << x.bit_length()) | x
        return v

