class Solution {
    static int cat(int a, int b) {
        int bl = 0;
        while ((1 << bl) <= b) bl++;
        return (a << bl) | b;
    }
public:
    int maxGoodNumber(vector<int>& nums) {
        sort(nums.begin(), nums.end(), [](int a, int b) { return cat(a, b) > cat(b, a); });
        int v = 0;
        for (int x : nums) v = (v << (32 - __builtin_clz(x))) | x;
        return v;
    }
};

