class Solution {
    private static long cat(int a, int b) {
        int bl = 32 - Integer.numberOfLeadingZeros(b);
        return ((long) a << bl) | b;
    }
    public int maxGoodNumber(int[] nums) {
        Integer[] arr = new Integer[nums.length];
        for (int i = 0; i < nums.length; i++) arr[i] = nums[i];
        Arrays.sort(arr, (a, b) -> Long.compare(cat(b, a), cat(a, b)));
        int v = 0;
        for (int x : arr) v = (v << (32 - Integer.numberOfLeadingZeros(x))) | x;
        return v;
    }
}

